  $('#rv-ver').onclick=()=>$('#rv-f').click();$('#rv-f').onchange=async e=>{const fi=e.target.files[0];if(!fi)return;const nota=prompt('Nota desta versão (opcional):','')||'';const u2=await lerFicheiroURL(fi);r.versoes=r.versoes||[];r.versoes.push({v:r.versoes.length+1,doc:guardarDoc(u2),nome:fi.name,mime:fi.type,tam:fi.size,q:Date.now(),nota});r.atual=Date.now();saveNow();audit('Biblioteca','Nova versão',r.titulo+' v'+r.versoes.length);verRecurso(id);vRecursos()};
