  const md=$('#rv-mod');if(md)md.onclick=()=>{const c=JSON.parse(JSON.stringify(r));c.id=uid();c.tipo='modelo';c.titulo='Modelo — '+r.titulo;c.colecao='Modelos';c.criado=c.atual=Date.now();recursos().push(c);saveNow();toast('Modelo criado','ok');vRecursos()};
