      const AL=ctx.dt?alunosDaClasse(a,ctx.dt):tt?alunosTodos(tt).map(x=>({x,reg:[{t:tt,x}]})):[];const sel=UI.docAl||(ctx.aluno?[ctx.aluno]:[]);
