    ['dc-txt','dc-tit','dc-ass'].forEach(i=>$('#'+i).addEventListener('input',()=>{UI.docTxt=$('#dc-txt').value;UI.docTit=$('#dc-tit').value;UI.docAss=$('#dc-ass').value;pv()}));
    $('#dc-t').onchange=()=>{UI.docTurma=$('#dc-t').value;UI.docAl=[];vDocumentos()};$$('[data-dcal]').forEach(c=>c.onchange=()=>{UI.docAl=$$('[data-dcal]').filter(z=>z.checked).map(z=>z.dataset.dcal);pv()});
